        ObjectNode legacy=Captures.compareCaptures(compact,CaptureTools.projectViewerSnapshot(store.projection(afterId),null,null)),comparison=CaptureTools.compareSavedSnapshots(store,beforeId,afterId);assertEquals(legacy.path("nesting"),comparison.path("nesting"));assertEquals(legacy.path("methods"),comparison.path("methods"));JsonNode roots=comparison.path("behavior").path("methods");assertEquals(1,roots.size());assertEquals("A",roots.get(0).path("methodName").asText());assertEquals(2,roots.get(0).path("nestedChangedCount").asInt());assertEquals("E",methodNamed(roots.get(0).path("nestedChanges"),"E").path("methodName").asText());
